    /**
     * 提交处罚申诉：当事人针对自己一条已生效且未被申诉的处罚，在 finishAt 后30分钟内提交。
     * 受理冻结处罚、原始/净成绩、分段判定与榜单版本，状态 PENDING；榜单版本不变、
     * 公开榜单仍按原处罚计算但标记该选手“申诉中”。
     */
    ServiceResult submitAppeal(
            String raceId, String penaltyId, SubmitAppealRequest request);

    /**
